import{_ as e,c as a,o as r,b0 as d}from"./chunks/framework.Dmsv_Tiv.js";const n="/media-docs/assets/image-20251212110237226.C7q3MSvM.png",S=JSON.parse('{"title":"LV010-AES简介","description":null,"frontmatter":{"title":"LV010-AES简介","date":"2025-12-12T10:57:47.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/encryption/126b1a4dc81319f5e08842b7","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-12T10:57:47.415Z","fulluuid":"5e08842b7f014f1e8ffc860739cb08ab","useduuid":"5e08842b7"}},"headers":[],"relativePath":"sdoc/vcodec/encryption/126b1a4dc81319f5e08842b7.md","filePath":"sdoc/20-视频编解码/60-加解密/LV010-AES简介.md","lastUpdated":1767537778000}'),o={name:"sdoc/vcodec/encryption/126b1a4dc81319f5e08842b7.md"};function l(h,t,s,i,c,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="lv010-aes简介" tabindex="-1">LV010-AES简介 <a class="header-anchor" href="#lv010-aes简介" aria-label="Permalink to &quot;LV010-AES简介&quot;">​</a></h1><h2 id="一、aes-简介" tabindex="-1">一、AES 简介 <a class="header-anchor" href="#一、aes-简介" aria-label="Permalink to &quot;一、AES 简介&quot;">​</a></h2><p><strong>高级加密标准</strong>（英语：<strong>A</strong> dvanced <strong>E</strong> ncryption <strong>S</strong> tandard，<a href="https://www.wikiwand.com/zh-cn/%E7%BC%A9%E5%86%99" target="_blank" rel="noreferrer">缩写</a>：AES），又称 <strong>Rijndael 加密法</strong>（荷兰语发音：[<a href="https://www.wikiwand.com/zh-cn/Help:%E8%8D%B7%E8%98%AD%E8%AA%9E%E5%9C%8B%E9%9A%9B%E9%9F%B3%E6%A8%99" target="_blank" rel="noreferrer">ˈrɛindaːl]</a>，音似英文的“Rhine doll”），是 <a href="https://www.wikiwand.com/zh-cn/%E7%BE%8E%E5%9B%BD%E8%81%94%E9%82%A6%E6%94%BF%E5%BA%9C" target="_blank" rel="noreferrer">美国联邦政府</a> 采用的一种 <a href="https://www.wikiwand.com/zh-cn/%E5%8D%80%E5%A1%8A%E5%8A%A0%E5%AF%86" target="_blank" rel="noreferrer">区块加密</a> 标准。这个标准用来替代原先的 <a href="https://www.wikiwand.com/zh-cn/DES" target="_blank" rel="noreferrer">DES</a>，已经被多方分析且广为全世界所使用。经过五年的甄选流程，高级加密标准由 <a href="https://www.wikiwand.com/zh-cn/%E7%BE%8E%E5%9B%BD%E5%9B%BD%E5%AE%B6%E6%A0%87%E5%87%86%E4%B8%8E%E6%8A%80%E6%9C%AF%E7%A0%94%E7%A9%B6%E9%99%A2" target="_blank" rel="noreferrer">美国国家标准与技术研究院</a>（NIST）于 2001 年 11 月 26 日发布于 FIPS PUB 197，并在 2002 年 5 月 26 日成为有效的标准。现在，高级加密标准已然成为 <a href="https://www.wikiwand.com/zh-cn/%E5%AF%B9%E7%A7%B0%E5%AF%86%E9%92%A5%E5%8A%A0%E5%AF%86" target="_blank" rel="noreferrer">对称密钥加密</a> 中最流行的 <a href="https://www.wikiwand.com/zh-cn/%E6%BC%94%E7%AE%97%E6%B3%95" target="_blank" rel="noreferrer">算法</a> 之一。</p><blockquote><p>AES 的产生是为了解决 DES 存在的密钥长度过短、安全性不足等问题，以适应当时互联网和电子商务快速发展的需求。</p></blockquote><p>它是一种分组加密标准，每个加密块大小为 128 位，允许的密钥长度为 128、192 和 256 位。它是一种 <strong>对称加密算法</strong>，它是目前应用最广泛的加密算法之一。AES 算法具有高效性、安全性和可靠性，被广泛用于数据保护、网络通信以及安全传输等领域。</p><p><img src="'+n+'" alt="image-20251212110237226"></p><h2 id="二、aes-安全性" tabindex="-1">二、AES 安全性 <a class="header-anchor" href="#二、aes-安全性" aria-label="Permalink to &quot;二、AES 安全性&quot;">​</a></h2><h3 id="_1-安全性分析" tabindex="-1">1. 安全性分析 <a class="header-anchor" href="#_1-安全性分析" aria-label="Permalink to &quot;1. 安全性分析&quot;">​</a></h3><h4 id="_1-1-轮数与密钥长度" tabindex="-1">1.1 轮数与密钥长度 <a class="header-anchor" href="#_1-1-轮数与密钥长度" aria-label="Permalink to &quot;1.1 轮数与密钥长度&quot;">​</a></h4><p>AES 为分组密码，分组密码也就是把明文分成一组一组的，每组长度相等，每次加密一组数据，直到加密完整个明文。在 AES 标准规范中，分组长度只能是 128 位，也就是说，每个分组为 16 个字节（每个字节 8 位）。密钥的长度可以使用 128 位、192 位或 256 位。密钥的长度不同，推荐加密轮数也不同，如下表所示：</p><table tabindex="0"><thead><tr><th style="text-align:center;">AES</th><th style="text-align:center;">密钥长度（32 位比特字)</th><th style="text-align:center;">分组长度(32 位比特字)</th><th style="text-align:center;">加密轮数</th></tr></thead><tbody><tr><td style="text-align:center;">AES-128</td><td style="text-align:center;">4</td><td style="text-align:center;">4</td><td style="text-align:center;">10</td></tr><tr><td style="text-align:center;">AES-192</td><td style="text-align:center;">6</td><td style="text-align:center;">4</td><td style="text-align:center;">12</td></tr><tr><td style="text-align:center;">AES-256</td><td style="text-align:center;">8</td><td style="text-align:center;">4</td><td style="text-align:center;">14</td></tr></tbody></table><p>一般来说，密钥长度越长，破解难度越大，安全性越高。推荐使用 256 位密钥以获得最高级别的安全性。AES 的安全性与轮数有关，一般 128 位密钥对应 10 轮，192 位密钥对应 12 轮，256 位密钥对应 14 轮。增加轮数可以增强加密算法的安全性，但也会增加计算成本。</p><blockquote><p>选择 AES 的密钥长度时，应根据所需的安全级别和性能需求来决定：</p><p>（1）对于一般应用，128 位密钥已经足够安全，而且具有较好的性能表现。</p><p>（2）如果需要更高级别的安全性，可以选择 192 位或 256 位密钥。256 位密钥提供了最高级别的安全性，但会增加加密和解密的计算成本。</p><p>（3）在实际应用中，应权衡安全性和性能需求，选择合适的密钥长度。</p></blockquote><h4 id="_1-2-s-盒设计" tabindex="-1">1.2 S 盒设计 <a class="header-anchor" href="#_1-2-s-盒设计" aria-label="Permalink to &quot;1.2 S 盒设计&quot;">​</a></h4><p>AES 的 S 盒（Substitution Box）经过专门设计，具有良好的非线性性和扩散性，增强了 AES 的安全性。S 盒的设计是 AES 抵抗差分攻击和线性攻击的关键。</p><blockquote><p>S 盒是什么？<a href="https://omni.wikiwand.com/zh/articles/S%E7%9B%92" target="_blank" rel="noreferrer">S 盒 - Wikiwand / articles</a></p><p>在密码学中，一个 S 盒（Substitution-box，替换盒）是对称密钥加密算法执行替换计算的基本结构。在块密码中，它们通常用于模糊密钥与密文之间的关系——香农的混淆理论。</p><p>通常，S-Box 接受特定数量的输入比特 m，并将其转换为特定数量的输出比特 n，其中 n 不一定等于 m。一个 m×n 的 S 盒可以通过包含 2m 条目，每条目 n 比特的查找表实现。S 盒通常是固定的（例如 DES 和 AES 加密算法）, 也有一些加密算法的 S 盒是基于密钥动态生成的（例如 Blowfish 和双鱼算法加密算法）。DES 的 6×4 位 S 盒（S5）是一个很好的例子：</p><table><tr><th rowspan="2" colspan="2" align="center"> S <sub> 5 </sub></th><th colspan="16" align="center"> 中间四个比特 </th></tr><tr><th> 0000 </th><th> 0001 </th><th> 0010 </th><th> 0011 </th><th> 0100 </th><th> 0101 </th><th> 0110 </th><th> 0111 </th><th> 1000 </th><th> 1001 </th><th> 1010 </th><th> 1011 </th><th> 1100 </th><th> 1101 </th><th> 1110 </th><th> 1111 </th></tr><tr><th rowspan="4"> 首尾比特 </th><th> 00 </th><td> 0010 </td><td> 1100 </td><td> 0100 </td><td> 0001 </td><td> 0111 </td><td> 1010 </td><td> 1011 </td><td> 0110 </td><td> 1000 </td><td> 0101 </td><td> 0011 </td><td> 1111 </td><td> 1101 </td><td> 0000 </td><td> 1110 </td><td> 1001 </td></tr><tr><th> 01 </th><td> 1110 </td><td> 1011 </td><td> 0010 </td><td> 1100 </td><td> 0100 </td><td> 0111 </td><td> 1101 </td><td> 0001 </td><td> 0101 </td><td> 0000 </td><td> 1111 </td><td> 1010 </td><td> 0011 </td><td> 1001 </td><td> 1000 </td><td> 0110 </td></tr><tr><th> 10 </th><td> 0100 </td><td> 0010 </td><td> 0001 </td><td> 1011 </td><td> 1010 </td><td> 1101 </td><td> 0111 </td><td> 1000 </td><td> 1111 </td><td> 1001 </td><td> 1100 </td><td> 0101 </td><td> 0110 </td><td> 0011 </td><td> 0000 </td><td> 1110 </td></tr><tr><th> 11 </th><td> 1011 </td><td> 1000 </td><td> 1100 </td><td> 0111 </td><td> 0001 </td><td> 1110 </td><td> 0010 </td><td> 1101 </td><td> 0110 </td><td> 1111 </td><td> 0000 </td><td> 1001 </td><td> 1010 </td><td> 0100 </td><td> 0101 </td><td> 0011 </td></tr></table><p>给定 6 比特输入，将首尾两个比特作为行条件、中间四个比特（inner four bits）作为列条件进行查表，最终获得 4 比特输出。例如，输入“011011”，通过首尾两个比特“01”和中间的比特“1101”进行查表，最终的输出应该是“1001”。</p></blockquote><h4 id="_1-3-密钥调度算法" tabindex="-1">1.3 密钥调度算法 <a class="header-anchor" href="#_1-3-密钥调度算法" aria-label="Permalink to &quot;1.3 密钥调度算法&quot;">​</a></h4><p>AES 使用密钥调度算法生成轮密钥，确保生成的轮密钥与原始密钥无关，增加了密码的复杂性，提高了安全性。</p><h3 id="_2-抗攻击性能" tabindex="-1">2. 抗攻击性能 <a class="header-anchor" href="#_2-抗攻击性能" aria-label="Permalink to &quot;2. 抗攻击性能&quot;">​</a></h3><p>AES 具有很好的抗攻击性能，主要表现在以下几个方面：</p><p><strong>差分攻击（Differential Cryptanalysis）：</strong> AES 对差分攻击有较好的抵抗能力，这种攻击方式需要大量的明文-密文对来分析密码算法的性质，而 AES 的 S 盒设计和轮函数的复杂性使得差分攻击变得更加困难。</p><p><strong>线性攻击（Linear Cryptanalysis）：</strong> AES 对线性攻击也有较好的抵抗能力，线性攻击利用线性逼近的特性来破解密码算法，AES 的设计使得线性攻击难以成功。</p><h2 id="三、aes-的应用" tabindex="-1">三、AES 的应用 <a class="header-anchor" href="#三、aes-的应用" aria-label="Permalink to &quot;三、AES 的应用&quot;">​</a></h2><h3 id="_1-在数据加密中的应用" tabindex="-1">1. 在数据加密中的应用 <a class="header-anchor" href="#_1-在数据加密中的应用" aria-label="Permalink to &quot;1. 在数据加密中的应用&quot;">​</a></h3><p>AES 在数据加密中被广泛应用，用于保护数据的机密性和完整性。以下是 AES 在数据加密中的一些常见应用：</p><p>（1）<strong>文件加密：</strong> AES 可用于加密文件，确保文件在存储或传输过程中不被未经授权的访问者获取。</p><p>（2）<strong>数据库加密：</strong> 数据库中的敏感数据可以使用 AES 进行加密，以防止数据库泄露导致数据泄露。</p><p>（3）<strong>通信加密：</strong> 在网络通信中，AES 可用于加密通信内容，确保通信数据的机密性，防止被窃听者获取敏感信息。</p><p>（4）<strong>移动设备加密：</strong> 移动设备中的数据可以使用 AES 进行加密，保护用户的个人信息和隐私数据。</p><h3 id="_2-在网络安全中的应用" tabindex="-1">2. 在网络安全中的应用 <a class="header-anchor" href="#_2-在网络安全中的应用" aria-label="Permalink to &quot;2. 在网络安全中的应用&quot;">​</a></h3><p>AES 在网络安全中扮演着重要的角色，用于保护网络通信的安全性。以下是 AES 在网络安全中的一些应用：</p><p>（1）<strong>VPN 加密：</strong> 虚拟私人网络（VPN）中的数据通常使用 AES 进行加密，确保远程访问者和分支机构之间的通信安全。</p><p>（2）<strong>SSL/TLS 加密：</strong> 在 Web 通信中，SSL/TLS 协议使用 AES 加密算法来保护网站和用户之间的数据传输，确保数据的机密性。</p><p>（3）<strong>数据包加密：</strong> 网络数据包可以使用 AES 进行加密，防止中间人攻击和数据篡改。</p><p>（4）<strong>数字签名：</strong> AES 也可以与数字签名算法结合使用，确保数据的完整性和认证性。</p><h3 id="_3-在软件和硬件中的实现" tabindex="-1">3. 在软件和硬件中的实现 <a class="header-anchor" href="#_3-在软件和硬件中的实现" aria-label="Permalink to &quot;3. 在软件和硬件中的实现&quot;">​</a></h3><p>AES 可以在软件和硬件中实现，提供数据加密和解密功能。在软件中，AES 通常通过调用加密库或使用加密算法实现。在硬件中，AES 可以通过专用的加密芯片或 FPGA 实现加速加密运算。</p><p>在软件中实现 AES 时，可以使用各种编程语言（如 C、C++、Java 等）提供的加密库，或者使用开源的加密算法库（如 OpenSSL、Crypto++等）来实现 AES 算法。</p><p>在硬件中实现 AES 时，可以使用专门设计的加密芯片（如 TPM 芯片）或者使用 FPGA（现场可编程门阵列）来加速 AES 加密运算。硬件实现通常能提供更高的性能和安全性，适用于对加密性能要求较高的场景。</p><blockquote><p>参考资料：</p><p><a href="https://www.cnblogs.com/Amd794/p/18153705" target="_blank" rel="noreferrer">深入理解高级加密标准（Advanced Encryption Standard） - Amd794 - 博客园</a></p><p><a href="https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.197-upd1.pdf" target="_blank" rel="noreferrer">Advanced Encryption Standard (AES)</a></p><p><a href="https://www.veritas.com/zh/cn/information-center/aes-encryption" target="_blank" rel="noreferrer">高级加密标准：AES 加密终极指南 | Veritas</a></p></blockquote>',40)])])}const A=e(o,[["render",l]]);export{S as __pageData,A as default};
